// src/parked-turn.ts
var PARKED_PROBE_MAX_BYTES = 512 * 1024;
var CREATED_AT_TOLERANCE_MS = 2000;
function extractParkedAnswer(tail, turnStartedMs) {
  const lines = tail.split(`
`);
  for (let i = lines.length - 1;i >= 0; i -= 1) {
    const line = lines[i]?.trim();
    if (!line)
      continue;
    let step;
    try {
      step = JSON.parse(line);
    } catch {
      continue;
    }
    if (typeof step.created_at !== "string")
      continue;
    const createdAtMs = Date.parse(step.created_at);
    if (Number.isNaN(createdAtMs))
      continue;
    if (createdAtMs < turnStartedMs - CREATED_AT_TOLERANCE_MS)
      break;
    if (step.source !== "MODEL" || step.status !== "DONE")
      return;
    if (step.type !== "PLANNER_RESPONSE")
      return;
    if (Array.isArray(step.tool_calls) && step.tool_calls.length > 0)
      return;
    if (typeof step.content !== "string" || step.content.length === 0)
      return;
    return step.content;
  }
  return;
}
async function readTranscriptTail(filePath, maxBytes) {
  let handle;
  try {
    handle = await open2(filePath, "r");
  } catch {
    return "";
  }
  try {
    const { size } = await handle.stat();
    const start = Math.max(0, size - maxBytes);
    const length = size - start;
    const buffer = Buffer.alloc(length);
    let read = 0;
    while (read < length) {
      const { bytesRead } = await handle.read(buffer, read, length - read, start + read);
      if (bytesRead === 0)
        break;
      read += bytesRead;
    }
    return buffer.subarray(0, read).toString("utf8");
  } catch {
    return "";
  } finally {
    await handle.close().catch(() => {});
  }
}
async function parkedTurnAnswer(conversationId, turnStartedMs, home = undefined) {
  const transcript = `${agyConversationDir("stream-json", conversationId, home)}/.system_generated/logs/transcript_full.jsonl`;
  const tail = await readTranscriptTail(transcript, PARKED_PROBE_MAX_BYTES);
  if (tail === "")
    return;
  return extractParkedAnswer(tail, turnStartedMs);
}

