// src/omp/pickers.ts
function selectOmp(ui, title, options, dialogOptions) {
  const omp = ui;
  return omp.select(title, options, dialogOptions);
}
async function hostDialogChoice() {
  if (!isOmpHost())
    return (await importLegacyDialogs()).dialogChoice;
  return async (ctx, title, { options, description, footer }) => {
    const picked = await selectOmp(ctx.ui, description ? `${title}
${description}` : title, options.map((option) => ({ label: option.label, description: option.description })), { helpText: typeof footer === "string" ? footer : footer?.join(" \xB7 ") });
    return options.find((option) => option.label === picked)?.value;
  };
}
async function ompArtifactsBrowser(ui, artifacts, items) {
  if (!isOmpHost())
    return;
  const rescan = { label: "Rescan", description: "Scan this conversation's artifacts again" };
  const options = items.map((item, index) => ({ label: `${index + 1}. ${item.label}`, description: item.description }));
  const picked = await selectOmp(ui, `Antigravity artifacts (${artifacts.length})`, [...options, rescan], {
    helpText: "enter open \xB7 esc close"
  });
  if (picked === rescan.label)
    return { type: "rescan" };
  const index = options.findIndex((option) => option.label === picked);
  return index >= 0 ? { type: "open", artifact: artifacts[index] } : { type: "close" };
}
async function ompTasksBrowser(ui, items, livenessKnown) {
  if (!isOmpHost())
    return;
  const rescan = { label: "Rescan", description: "Scan this conversation's background tasks again" };
  const title = [
    `Antigravity tasks (${items.length})`,
    ...livenessKnown ? [] : ["lsof not found; liveness unknown (install lsof for ACTIVE/idle)"],
    "/agy tasks tail <id> for a log"
  ].join(`
`);
  const options = items.map((item) => ({ label: item.label, description: item.description }));
  const picked = await selectOmp(ui, title, [...options, rescan], { helpText: "enter close \xB7 esc close" });
  return picked === rescan.label ? { type: "rescan" } : { type: "close" };
}
async function ompSettingsMenu(ui, menu) {
  const width = Math.max(...menu.rows.map((row) => row.label.length));
  let cursor = 0;
  for (;; ) {
    const options = menu.rows.map((row) => ({
      label: `${row.label.padEnd(width)}  ${row.currentValue}`,
      description: row.description
    }));
    const picked = await selectOmp(ui, `${menu.title}
${menu.subtitle}`, options, {
      helpText: "enter cycle/open \xB7 esc close",
      initialIndex: cursor
    });
    cursor = options.findIndex((option) => option.label === picked);
    const row = menu.rows[cursor];
    if (!row)
      return;
    if (!row.values?.length)
      return row.id;
    const next = row.values[(row.values.indexOf(row.currentValue) + 1) % row.values.length];
    row.currentValue = next;
    menu.onChange(row.id, next);
  }
}

