  gif: "image",
  webp: "image",
  svg: "image",
  bmp: "image",
  mp3: "audio",
  wav: "audio",
  ogg: "audio",
  m4a: "audio",
  flac: "audio",
  mp4: "video",
  mov: "video",
  webm: "video",
  mkv: "video",
  pdf: "pdf",
  md: "markdown",
  markdown: "markdown",
