// src/daily-log.ts
import { appendFile, mkdir, readdir as readdir3, unlink } from "fs/promises";
import path22 from "path";
function dayKey(d) {
  const p = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}
var MAX_STRING = 2000;
var MAX_DEPTH = 6;
var MAX_RECORD = 4000;
var SECRET_KEY = /token|secret|password|passphrase|authorization|api[-_]?key|cookie|headers/i;
function scrub(value, depth) {
  if (value === null || value === undefined)
    return value;
  if (value instanceof Error) {
    return {
      name: value.name,
      message: scrub(value.message, depth),
      stack: scrub(value.stack, depth)
    };
  }
  if (typeof value === "string") {
    const clean = redactText(value);
    return clean.length > MAX_STRING ? clean.slice(0, MAX_STRING) + "\u2026(truncated)" : clean;
  }
  if (typeof value === "number" || typeof value === "boolean")
    return value;
  if (depth >= MAX_DEPTH)
    return "(depth limit)";
  if (Array.isArray(value))
    return value.slice(0, 50).map((v) => scrub(v, depth + 1));
  if (typeof value === "object") {
    const out = {};
    for (const [k, v] of Object.entries(value)) {
      out[k] = SECRET_KEY.test(k) ? "[redacted]" : scrub(v, depth + 1);
    }
    return out;
  }
  return String(value);
}
function isEnvTruthy(v) {
  return v !== undefined && ["1", "true", "on"].includes(v.toLowerCase());
}
function createDailyLogger(opts) {
  const dir = opts.dir;
  const retentionDays = opts.retentionDays ?? 14;
  const verbose = opts.debug ?? isEnvTruthy(process.env.AGY_DEBUG);
  const now = opts.now ?? (() => new Date);
  let chain = Promise.resolve();
  let ensuredDay = "";
  let pruned = false;
  async function prune() {
    if (pruned)
      return;
    pruned = true;
    const cutoff = dayKey(new Date(now().getTime() - retentionDays * 86400000));
    const names = await readdir3(dir).catch(() => []);
    for (const name of names) {
      if (!name.endsWith(".ndjson"))
        continue;
      if (name.slice(0, 10) >= cutoff)
        continue;
      await unlink(path22.join(dir, name)).catch(() => {});
    }
  }
  function write(level, event, data) {
    const d = now();
    const day = dayKey(d);
    let line;
    try {
      const record = {
        ts: d.toISOString(),
        level,
        event
      };
      if (data !== undefined)
        record.data = scrub(data, 0);
      line = JSON.stringify(record);
      if (line.length > MAX_RECORD) {
        record.data = `(record exceeded ${MAX_RECORD} bytes; payload dropped)`;
        line = JSON.stringify(record);
      }
      line += `
`;
    } catch {
      line = `${JSON.stringify({ ts: d.toISOString(), level, event, data: "(unserializable)" })}
`;
    }
    chain = chain.then(async () => {
      try {
        if (ensuredDay !== day) {
          await mkdir(dir, { recursive: true });
          ensuredDay = day;
          await prune();
        }
        await appendFile(path22.join(dir, `${day}.ndjson`), line, "utf8");
      } catch {
        try {
          ensuredDay = "";
          await mkdir(dir, { recursive: true });
          ensuredDay = day;
          await appendFile(path22.join(dir, `${day}.ndjson`), line, "utf8");
        } catch {}
      }
    });
  }
  return {
    log(event, data, level = "debug") {
      if (!verbose && level !== "error")
        return;
      write(level, event, data);
    },
    flush() {
      return chain.catch(() => {});
    },
    dir,
    todayPath() {
      return path22.join(dir, `${dayKey(now())}.ndjson`);
    }
  };
}

