var DIALOG_LOCK = Symbol.for("pi-me.dialog-lock");
function dialogQueue() {
  const host = globalThis;
  const existing = host[DIALOG_LOCK];
  if (existing)
    return existing;
  const created = { tail: Promise.resolve() };
  host[DIALOG_LOCK] = created;
  return created;
}
async function withDialogLock(run) {
  const queue = dialogQueue();
  const prev = queue.tail;
  let release;
  queue.tail = new Promise((resolve) => {
    release = resolve;
  });
  await prev;
  try {
    return await run();
  } finally {
    release();
  }
}

